42: func NewStore(databasePath string) (*Store, error) {
43: 	db, err := sql.Open("sqlite", databasePath)
44: 	if err != nil {
45: 		return nil, fmt.Errorf("open todo database: %w", err)
46: 	}
47: 	db.SetMaxOpenConns(1)
48: 
49: 	if _, err := db.Exec(`
50: 		PRAGMA busy_timeout = 5000;
51: 		CREATE TABLE IF NOT EXISTS todos (
52: 			id INTEGER PRIMARY KEY AUTOINCREMENT,
53: 			title TEXT NOT NULL,
54: 			completed INTEGER NOT NULL DEFAULT 0,
55: 			created_at TEXT NOT NULL,
56: 			updated_at TEXT NOT NULL
57: 		);
58: 	`); err != nil {
59: 		db.Close()
60: 		return nil, fmt.Errorf("initialize todo database: %w", err)
61: 	}
62: 
63: 	return &Store{db: db}, nil
64: }
